edits.after:
if (ref_change > 0) {
	if (ref_count <= 0)
		ext4_warning_inode(ea_inode, "EA inode %lu ref_count=%lld",
				   ea_inode->i_ino, ref_count);

	if (ref_count == 1) {
		if (ea_inode->i_nlink)
			ext4_warning_inode(ea_inode, "EA inode %lu i_nlink=%u",
					   ea_inode->i_ino, ea_inode->i_nlink);

		set_nlink(ea_inode, 1);
		ext4_orphan_del(handle, ea_inode);
	}
} else {
	if (ref_count < 0)
		ext4_warning_inode(ea_inode, "EA inode %lu ref_count=%lld",
				   ea_inode->i_ino, ref_count);

	if (ref_count == 0) {
		if (ea_inode->i_nlink != 1)
			ext4_warning_inode(ea_inode, "EA inode %lu i_nlink=%u",
					   ea_inode->i_ino, ea_inode->i_nlink);

		clear_nlink(ea_inode);
		ext4_orphan_add(handle, ea_inode);
	}
}

